#include <stdio.h>

#define FLAG_READ  0x01U
#define FLAG_WRITE 0x02U
#define FLAG_EXEC  0x04U

int main(void)
{
    unsigned int flags = 0U;
    flags |= FLAG_READ | FLAG_WRITE;
    printf("write=%s\n", (flags & FLAG_WRITE) != 0U ? "yes" : "no");
    flags &= ~FLAG_WRITE;
    flags ^= FLAG_EXEC;
    printf("read=%u exec=%u\n",
           (flags & FLAG_READ) != 0U,
           (flags & FLAG_EXEC) != 0U);
    return 0;
}

#include <limits.h>
#include <stdio.h>

int main(void)
{
    unsigned int word = 0x2DU;
    unsigned int shift = 2U;
    unsigned int field_mask = 0x07U;
    unsigned int field;

    if (shift >= sizeof word * CHAR_BIT) {
        return 1;
    }
    field = (word >> shift) & field_mask;
    printf("field=%u\n", field);
    return 0;
}
